dt-example.js:
new DataTable('#example', {
	columnDefs: [
		{
			orderable: false,
			render: DataTable.render.select(),
			targets: 0
		}
	],
	layout: {
		topStart: {
			buttons: ['stateCreate', 'statesList']
		}
	},
	order: [[1, 'asc']],
	select: {
		style: 'os',
		selector: 'td:first-child'
	},
	stateRestore: {
		include: {
			select: null
		}
	}
});
